    val all = listOf(
        ShortLesson("MATEMATICAS:0:0", MateriaId.MATEMATICAS, 0, "Valor posicional", "El valor de una cifra depende de su posición. De derecha a izquierda aparecen unidades, decenas y centenas.", "En 352, el 3 representa 300, el 5 representa 50 y el 2 representa 2.", "Decena: Grupo de diez unidades.", listOf("Decena" to "Grupo de diez unidades", "Centena" to "Grupo de cien unidades"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Grupo de diez unidades.", listOf("Decena", "Centena"), 0, "Decena: Grupo de diez unidades."), ShortQuestion("En el número 406, ¿qué posición ocupa el 4?", listOf("Decena", "Centena"), 1, "Centena: Grupo de cien unidades.")), null, "es-MX", null, gapAnswer = "Decena"),
        ShortLesson("MATEMATICAS:0:1", MateriaId.MATEMATICAS, 0, "Fracciones", "Una fracción expresa partes iguales de una unidad. El denominador indica cuántas partes iguales hay y el numerador cuántas se consideran.", "Si divides una figura en cuatro partes iguales y marcas tres, has marcado 3/4.", "Numerador: Número de partes consideradas.", listOf("Numerador" to "Número de partes consideradas", "Denominador" to "Número de partes iguales de la unidad"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Número de partes consideradas.", listOf("Numerador", "Denominador"), 0, "Numerador: Número de partes consideradas."), ShortQuestion("En 3/8, ¿cómo se llama el número 3?", listOf("Numerador", "Denominador"), 0, "Numerador: Número de partes consideradas.")), null, "es-MX", null, gapAnswer = "Numerador"),
        ShortLesson("MATEMATICAS:1:0", MateriaId.MATEMATICAS, 1, "Ecuaciones", "Una ecuación afirma que dos expresiones tienen el mismo valor. Sumar o restar la misma cantidad en ambos lados conserva la igualdad.", "Para resolver x + 3 = 8, resta 3 en ambos lados: x = 5.", "Incógnita: Valor que se busca en una ecuación.", listOf("Incógnita" to "Valor que se busca en una ecuación", "Solución" to "Valor que hace verdadera la igualdad"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Valor que se busca en una ecuación.", listOf("Incógnita", "Solución"), 0, "Incógnita: Valor que se busca en una ecuación."), ShortQuestion("Al comprobar x + 3 = 8, el valor 5 hace verdadera la igualdad. ¿Qué representa ese 5?", listOf("Incógnita", "Solución"), 1, "Solución: Valor que hace verdadera la igualdad.")), null, "es-MX", null, gapAnswer = "Incógnita"),
        ShortLesson("MATEMATICAS:1:1", MateriaId.MATEMATICAS, 1, "Área y perímetro", "El perímetro mide el contorno de una figura. El área mide la superficie que ocupa. En un rectángulo, el área es base por altura.", "Un rectángulo de 4 cm por 3 cm tiene área de 12 cm² y perímetro de 14 cm.", "Área: Medida de una superficie.", listOf("Área" to "Medida de una superficie", "Perímetro" to "Longitud del contorno"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Medida de una superficie.", listOf("Área", "Perímetro"), 0, "Área: Medida de una superficie."), ShortQuestion("Quieres colocar una cinta alrededor de un rectángulo. ¿Qué debes calcular?", listOf("Área", "Perímetro"), 1, "Perímetro: Longitud del contorno.")), null, "es-MX", "rectangle", gapAnswer = "Área"),
        ShortLesson("ESPANOL:0:0", MateriaId.ESPANOL, 0, "Sustantivos y verbos", "Un sustantivo nombra entidades, ideas o lugares. Un verbo expresa acciones, procesos o estados y puede conjugarse.", "En «La estudiante observa», estudiante es sustantivo y observa es verbo.", "Sustantivo: Palabra que nombra entidades o ideas.", listOf("Sustantivo" to "Palabra que nombra entidades o ideas", "Verbo" to "Palabra que expresa acciones, procesos o estados"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Palabra que nombra entidades o ideas.", listOf("Sustantivo", "Verbo"), 0, "Sustantivo: Palabra que nombra entidades o ideas."), ShortQuestion("En «María escribe», ¿qué clase de palabra es escribe?", listOf("Sustantivo", "Verbo"), 1, "Verbo: Palabra que expresa acciones, procesos o estados.")), null, "es-MX", null, gapAnswer = "Sustantivo"),
        ShortLesson("ESPANOL:0:1", MateriaId.ESPANOL, 0, "Sujeto y predicado", "El sujeto concuerda con el verbo en número y persona. El predicado expresa lo que se dice del sujeto.", "En «Los planetas orbitan el Sol», Los planetas es el sujeto y orbitan el Sol es el predicado.", "Sujeto: Parte que concuerda con el verbo.", listOf("Sujeto" to "Parte que concuerda con el verbo", "Predicado" to "Parte que expresa lo que se dice del sujeto"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Parte que concuerda con el verbo.", listOf("Sujeto", "Predicado"), 0, "Sujeto: Parte que concuerda con el verbo."), ShortQuestion("En «Los estudiantes leen», ¿qué función cumple Los estudiantes?", listOf("Sujeto", "Predicado"), 0, "Sujeto: Parte que concuerda con el verbo.")), null, "es-MX", null, gapAnswer = "Sujeto"),
        ShortLesson("ESPANOL:1:0", MateriaId.ESPANOL, 1, "Acentuación", "Las palabras agudas tienen la sílaba tónica al final y llevan tilde si terminan en vocal, n o s. Las esdrújulas tienen la tónica en la antepenúltima sílaba y siempre llevan tilde.", "Café es aguda y lleva tilde porque termina en vocal. Música es esdrújula.", "Aguda: Palabra con sílaba tónica final.", listOf("Aguda" to "Palabra con sílaba tónica final", "Esdrújula" to "Palabra con sílaba tónica antepenúltima"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Palabra con sílaba tónica final.", listOf("Aguda", "Esdrújula"), 0, "Aguda: Palabra con sílaba tónica final."), ShortQuestion("La sílaba tónica de música es mú. ¿Qué tipo de palabra es?", listOf("Aguda", "Esdrújula"), 1, "Esdrújula: Palabra con sílaba tónica antepenúltima.")), null, "es-MX", null, gapAnswer = "Aguda"),
        ShortLesson("ESPANOL:1:1", MateriaId.ESPANOL, 1, "Conectores", "Los conectores expresan relaciones entre ideas. Algunos indican causa y otros presentan una oposición.", "«No salimos porque llovía» expresa causa. «Llovía, sin embargo salimos» expresa contraste.", "Porque: Conector que introduce una causa.", listOf("Porque" to "Conector que introduce una causa", "Sin embargo" to "Conector que introduce un contraste"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Conector que introduce una causa.", listOf("Porque", "Sin embargo"), 0, "Porque: Conector que introduce una causa."), ShortQuestion("«El camino era largo; ___, llegamos a tiempo». ¿Qué conector expresa el contraste?", listOf("Porque", "Sin embargo"), 1, "Sin embargo: Conector que introduce un contraste.")), null, "es-MX", null, gapAnswer = "Porque"),
        ShortLesson("INGLES:0:0", MateriaId.INGLES, 0, "Presentarte", "I significa yo. Para decir tu nombre puedes usar My name is seguido del nombre. La forma I am también permite presentarte.", "My name is Ana. I am a student.", "My name is: Mi nombre es.", listOf("My name is" to "Mi nombre es", "I am" to "Yo soy o estoy"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Mi nombre es.", listOf("My name is", "I am"), 0, "My name is: Mi nombre es."), ShortQuestion("Quieres decir tu nombre. ¿Qué expresión debe ir antes de Ana?", listOf("My name is", "I am"), 0, "My name is: Mi nombre es.")), "My name is", "en-US", null, gapAnswer = "My name is"),
        ShortLesson("INGLES:0:1", MateriaId.INGLES, 0, "Preguntar por objetos", "What is this? pregunta qué es algo cercano. This is introduce la respuesta. A se usa delante de un sonido consonántico y an delante de un sonido vocálico.", "What is this? This is a book. This is an apple.", "What is this?: ¿Qué es esto?.", listOf("What is this?" to "¿Qué es esto?", "This is a book" to "Esto es un libro"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? ¿Qué es esto?.", listOf("What is this?", "This is a book"), 0, "What is this?: ¿Qué es esto?."), ShortQuestion("Señalas un objeto y preguntas qué es. ¿Qué dices?", listOf("What is this?", "This is a book"), 0, "What is this?: ¿Qué es esto?.")), "What is this?", "en-US", null, gapAnswer = "What is this?"),
        ShortLesson("INGLES:1:0", MateriaId.INGLES, 1, "Rutinas", "El presente simple expresa hábitos. Con I se usa la forma base del verbo; con he o she suele añadirse s.", "I study every day. She studies every day: study cambia y por ies tras consonante.", "I study: Yo estudio.", listOf("I study" to "Yo estudio", "She studies" to "Ella estudia"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Yo estudio.", listOf("I study", "She studies"), 0, "I study: Yo estudio."), ShortQuestion("Hablas de la rutina de ella. ¿Qué expresión utilizas?", listOf("I study", "She studies"), 1, "She studies: Ella estudia.")), "I study", "en-US", null, gapAnswer = "I study"),
        ShortLesson("INGLES:1:1", MateriaId.INGLES, 1, "Ubicación", "In indica estar dentro de algo; on indica estar sobre una superficie. La elección depende de la relación espacial.", "The book is on the table. The pen is in the bag.", "In the bag: Dentro de la bolsa.", listOf("In the bag" to "Dentro de la bolsa", "On the table" to "Sobre la mesa"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Dentro de la bolsa.", listOf("In the bag", "On the table"), 0, "In the bag: Dentro de la bolsa."), ShortQuestion("El bolígrafo está dentro de la bolsa. ¿Qué expresión indica esa ubicación?", listOf("In the bag", "On the table"), 0, "In the bag: Dentro de la bolsa.")), "In the bag", "en-US", null, gapAnswer = "In the bag"),
        ShortLesson("FRANCES:0:0", MateriaId.FRANCES, 0, "Presentarte", "Je significa yo. Je m’appelle se utiliza para decir el nombre. Bonjour es un saludo habitual durante el día.", "Bonjour. Je m’appelle Ana.", "Bonjour: Hola o buenos días.", listOf("Bonjour" to "Hola o buenos días", "Je m’appelle" to "Me llamo"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Hola o buenos días.", listOf("Bonjour", "Je m’appelle"), 0, "Bonjour: Hola o buenos días."), ShortQuestion("Entras a una tienda por la mañana y saludas. ¿Qué dices?", listOf("Bonjour", "Je m’appelle"), 0, "Bonjour: Hola o buenos días.")), "Bonjour", "fr-FR", null, gapAnswer = "Bonjour"),
        ShortLesson("FRANCES:0:1", MateriaId.FRANCES, 0, "Objetos y artículos", "En francés los sustantivos tienen género gramatical. Un es un artículo masculino y une es femenino.", "Un livre significa un libro. Une table significa una mesa.", "Un livre: Un libro.", listOf("Un livre" to "Un libro", "Une table" to "Una mesa"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Un libro.", listOf("Un livre", "Une table"), 0, "Un livre: Un libro."), ShortQuestion("¿Cómo se dice una mesa?", listOf("Un livre", "Une table"), 1, "Une table: Una mesa.")), "Un livre", "fr-FR", null, gapAnswer = "Un livre"),
        ShortLesson("FRANCES:1:0", MateriaId.FRANCES, 1, "Ser y tener", "Être expresa ser o estar; avoir expresa tener. En primera persona se usan je suis y j’ai.", "Je suis étudiant. J’ai un livre.", "Je suis: Yo soy o estoy.", listOf("Je suis" to "Yo soy o estoy", "J’ai" to "Yo tengo"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Yo soy o estoy.", listOf("Je suis", "J’ai"), 0, "Je suis: Yo soy o estoy."), ShortQuestion("Quieres decir que tienes un libro. ¿Cómo comienzas la frase?", listOf("Je suis", "J’ai"), 1, "J’ai: Yo tengo.")), "Je suis", "fr-FR", null, gapAnswer = "Je suis"),
