        ShortLesson("PORTUGUES:0:0", MateriaId.PORTUGUES, 0, "Presentarte", "Eu significa yo. Meu nome é permite decir tu nombre. Olá es un saludo.", "Olá. Meu nome é Ana.", "Olá: Hola.", listOf("Olá" to "Hola", "Meu nome é" to "Mi nombre es"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Hola.", listOf("Olá", "Meu nome é"), 0, "Olá: Hola."), ShortQuestion("Quieres presentar tu nombre. ¿Qué expresión usas?", listOf("Olá", "Meu nome é"), 1, "Meu nome é: Mi nombre es.")), "Olá", "pt-BR", null, gapAnswer = "Olá"),
