        ShortLesson("PORTUGUES:1:0", MateriaId.PORTUGUES, 1, "Ser y estar", "Sou es la primera persona de ser. Estou es la primera persona de estar y se usa, entre otros casos, para estados y ubicaciones.", "Eu sou estudante. Eu estou em casa.", "Sou estudante: Soy estudiante.", listOf("Sou estudante" to "Soy estudiante", "Estou em casa" to "Estoy en casa"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Soy estudiante.", listOf("Sou estudante", "Estou em casa"), 0, "Sou estudante: Soy estudiante."), ShortQuestion("Quieres indicar que estás en casa en este momento. ¿Qué dices?", listOf("Sou estudante", "Estou em casa"), 1, "Estou em casa: Estoy en casa.")), "Sou estudante", "pt-BR", null, gapAnswer = "Sou estudante"),
        ShortLesson("PORTUGUES:1:1", MateriaId.PORTUGUES, 1, "Cortesía", "Por favor permite hacer una petición cortés. Obrigado u obrigada expresan agradecimiento, según quien habla.", "Uma água, por favor. Obrigada.", "Por favor: Expresión para pedir con cortesía.", listOf("Por favor" to "Expresión para pedir con cortesía", "Obrigado" to "Gracias, dicho en forma masculina"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Expresión para pedir con cortesía.", listOf("Por favor", "Obrigado"), 0, "Por favor: Expresión para pedir con cortesía."), ShortQuestion("Pides agua de manera cortés. ¿Qué expresión añades?", listOf("Por favor", "Obrigado"), 0, "Por favor: Expresión para pedir con cortesía.")), "Por favor", "pt-BR", null, gapAnswer = "Por favor"),
        ShortLesson("ALEMAN:0:0", MateriaId.ALEMAN, 0, "Presentarte", "Ich significa yo. Ich heiße se usa para decir tu nombre. Hallo es un saludo informal.", "Hallo. Ich heiße Ana.", "Hallo: Hola.", listOf("Hallo" to "Hola", "Ich heiße" to "Me llamo"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Hola.", listOf("Hallo", "Ich heiße"), 0, "Hallo: Hola."), ShortQuestion("Quieres decir Me llamo Ana. ¿Qué expresión colocas antes de Ana?", listOf("Hallo", "Ich heiße"), 1, "Ich heiße: Me llamo.")), "Hallo", "de-DE", null, gapAnswer = "Hallo"),
        ShortLesson("ALEMAN:0:1", MateriaId.ALEMAN, 0, "Objetos y género", "Los sustantivos alemanes se escriben con mayúscula. Los artículos der, die y das indican género gramatical en nominativo singular.", "Das Buch significa el libro. Die Tasche significa la bolsa.", "Das Buch: El libro.", listOf("Das Buch" to "El libro", "Die Tasche" to "La bolsa"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? El libro.", listOf("Das Buch", "Die Tasche"), 0, "Das Buch: El libro."), ShortQuestion("¿Cómo se dice el libro?", listOf("Das Buch", "Die Tasche"), 0, "Das Buch: El libro.")), "Das Buch", "de-DE", null, gapAnswer = "Das Buch"),
        ShortLesson("ALEMAN:1:0", MateriaId.ALEMAN, 1, "Ser y tener", "Sein significa ser o estar; haben significa tener. En primera persona se usan ich bin e ich habe.", "Ich bin Student. Ich habe ein Buch.", "Ich bin: Yo soy o estoy.", listOf("Ich bin" to "Yo soy o estoy", "Ich habe" to "Yo tengo"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Yo soy o estoy.", listOf("Ich bin", "Ich habe"), 0, "Ich bin: Yo soy o estoy."), ShortQuestion("Quieres decir que tienes un libro. ¿Cómo comienzas la frase?", listOf("Ich bin", "Ich habe"), 1, "Ich habe: Yo tengo.")), "Ich bin", "de-DE", null, gapAnswer = "Ich bin"),
        ShortLesson("ALEMAN:1:1", MateriaId.ALEMAN, 1, "Cortesía", "Bitte puede significar por favor o de nada según el contexto. Danke expresa agradecimiento.", "Ein Wasser, bitte. Danke.", "Bitte: Por favor o de nada.", listOf("Bitte" to "Por favor o de nada", "Danke" to "Gracias"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Por favor o de nada.", listOf("Bitte", "Danke"), 0, "Bitte: Por favor o de nada."), ShortQuestion("Alguien te ayuda y quieres dar las gracias. ¿Qué dices?", listOf("Bitte", "Danke"), 1, "Danke: Gracias.")), "Bitte", "de-DE", null, gapAnswer = "Bitte"),
        ShortLesson("FISICA:0:0", MateriaId.FISICA, 0, "Magnitudes y unidades", "Una magnitud física es una propiedad medible. Su valor se expresa con un número y una unidad.", "Una mesa puede tener una longitud de 2 metros; el 2 es el valor numérico y metro es la unidad.", "Metro: Unidad de longitud.", listOf("Metro" to "Unidad de longitud", "Segundo" to "Unidad de tiempo"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Unidad de longitud.", listOf("Metro", "Segundo"), 0, "Metro: Unidad de longitud."), ShortQuestion("Un cronómetro registra cuánto dura una carrera. ¿Qué unidad corresponde a esa duración?", listOf("Metro", "Segundo"), 1, "Segundo: Unidad de tiempo.")), null, "es-MX", null, gapAnswer = "Metro"),
        ShortLesson("FISICA:0:1", MateriaId.FISICA, 0, "Rapidez media", "La rapidez media se obtiene al dividir distancia recorrida entre tiempo transcurrido. No informa de la dirección del movimiento.", "Si recorres 100 metros en 20 segundos, tu rapidez media es 5 m/s.", "Distancia: Longitud total del recorrido.", listOf("Distancia" to "Longitud total del recorrido", "Rapidez media" to "Distancia recorrida dividida entre tiempo"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Longitud total del recorrido.", listOf("Distancia", "Rapidez media"), 0, "Distancia: Longitud total del recorrido."), ShortQuestion("Divides 120 metros entre 30 segundos. ¿Qué magnitud obtienes?", listOf("Distancia", "Rapidez media"), 1, "Rapidez media: Distancia recorrida dividida entre tiempo.")), null, "es-MX", null, gapAnswer = "Distancia"),
        ShortLesson("FISICA:1:0", MateriaId.FISICA, 1, "Fuerza y aceleración", "Para masa constante, la fuerza neta es igual a masa por aceleración. Una fuerza neta distinta de cero cambia la velocidad.", "Una fuerza neta de 6 N sobre 2 kg produce una aceleración de 3 m/s².", "Fuerza neta: Suma vectorial de las fuerzas.", listOf("Fuerza neta" to "Suma vectorial de las fuerzas", "Aceleración" to "Cambio de velocidad por unidad de tiempo"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Suma vectorial de las fuerzas.", listOf("Fuerza neta", "Aceleración"), 0, "Fuerza neta: Suma vectorial de las fuerzas."), ShortQuestion("Sobre una caja actúan 8 N a la derecha y 3 N a la izquierda. ¿Qué representa el resultado de 5 N a la derecha?", listOf("Fuerza neta", "Aceleración"), 0, "Fuerza neta: Suma vectorial de las fuerzas.")), null, "es-MX", null, gapAnswer = "Fuerza neta"),
        ShortLesson("FISICA:1:1", MateriaId.FISICA, 1, "Energía", "La energía cinética está asociada al movimiento. La energía potencial depende de la configuración de un sistema.", "Una pelota que se mueve tiene energía cinética. Al elevarla aumenta su energía potencial gravitatoria respecto al suelo.", "Cinética: Energía asociada al movimiento.", listOf("Cinética" to "Energía asociada al movimiento", "Potencial" to "Energía asociada a la configuración"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Energía asociada al movimiento.", listOf("Cinética", "Potencial"), 0, "Cinética: Energía asociada al movimiento."), ShortQuestion("Una bicicleta se desplaza por una calle horizontal. ¿Qué energía está asociada a su movimiento?", listOf("Cinética", "Potencial"), 0, "Cinética: Energía asociada al movimiento.")), null, "es-MX", null, gapAnswer = "Cinética"),
        ShortLesson("QUIMICA:0:0", MateriaId.QUIMICA, 0, "El átomo", "Un átomo posee un núcleo con protones y, habitualmente, neutrones. Los electrones se distribuyen alrededor del núcleo.", "El átomo neutro de hidrógeno más común tiene un protón y un electrón, sin neutrones.", "Protón: Partícula con carga positiva.", listOf("Protón" to "Partícula con carga positiva", "Electrón" to "Partícula con carga negativa"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Partícula con carga positiva.", listOf("Protón", "Electrón"), 0, "Protón: Partícula con carga positiva."), ShortQuestion("Una partícula del átomo tiene carga negativa. ¿Cuál es?", listOf("Protón", "Electrón"), 1, "Electrón: Partícula con carga negativa.")), null, "es-MX", null, gapAnswer = "Protón"),
        ShortLesson("QUIMICA:0:1", MateriaId.QUIMICA, 0, "Elementos y compuestos", "Un elemento se define por el número de protones de sus átomos. Un compuesto contiene elementos unidos químicamente en proporciones definidas.", "El oxígeno es un elemento. El agua es un compuesto cuya fórmula es H₂O.", "Elemento: Sustancia formada por un tipo de átomo.", listOf("Elemento" to "Sustancia formada por un tipo de átomo", "Compuesto" to "Sustancia con elementos unidos químicamente"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Sustancia formada por un tipo de átomo.", listOf("Elemento", "Compuesto"), 0, "Elemento: Sustancia formada por un tipo de átomo."), ShortQuestion("Una sustancia contiene hidrógeno y oxígeno unidos en proporción definida. ¿Cómo se clasifica?", listOf("Elemento", "Compuesto"), 1, "Compuesto: Sustancia con elementos unidos químicamente.")), null, "es-MX", null, gapAnswer = "Elemento"),
        ShortLesson("QUIMICA:1:0", MateriaId.QUIMICA, 1, "Cambios de la materia", "Un cambio físico conserva la identidad química de las sustancias. Un cambio químico produce sustancias diferentes.", "Derretir hielo es un cambio físico. La oxidación del hierro es un cambio químico.", "Cambio físico: Transformación sin nuevas sustancias.", listOf("Cambio físico" to "Transformación sin nuevas sustancias", "Cambio químico" to "Transformación que produce nuevas sustancias"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Transformación sin nuevas sustancias.", listOf("Cambio físico", "Cambio químico"), 0, "Cambio físico: Transformación sin nuevas sustancias."), ShortQuestion("El hielo se derrite y sigue siendo agua. ¿Qué cambio ocurrió?", listOf("Cambio físico", "Cambio químico"), 0, "Cambio físico: Transformación sin nuevas sustancias.")), null, "es-MX", null, gapAnswer = "Cambio físico"),
        ShortLesson("QUIMICA:1:1", MateriaId.QUIMICA, 1, "Mezclas", "Una mezcla homogénea presenta composición uniforme a la escala observada. Una heterogénea presenta regiones distinguibles.", "La sal completamente disuelta en agua forma una mezcla homogénea. Agua y aceite separados forman una heterogénea.", "Homogénea: Mezcla de composición uniforme.", listOf("Homogénea" to "Mezcla de composición uniforme", "Heterogénea" to "Mezcla con regiones distinguibles"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Mezcla de composición uniforme.", listOf("Homogénea", "Heterogénea"), 0, "Homogénea: Mezcla de composición uniforme."), ShortQuestion("Tras reposar, agua y aceite forman dos capas. ¿Qué tipo de mezcla observas?", listOf("Homogénea", "Heterogénea"), 1, "Heterogénea: Mezcla con regiones distinguibles.")), null, "es-MX", null, gapAnswer = "Homogénea"),
        ShortLesson("BIOLOGIA:0:0", MateriaId.BIOLOGIA, 0, "La célula", "La célula es la unidad estructural y funcional básica de los seres vivos. La membrana delimita su interior y regula intercambios.", "Una bacteria es un organismo unicelular. Un árbol contiene muchas células especializadas.", "Membrana celular: Límite que regula intercambios.", listOf("Membrana celular" to "Límite que regula intercambios", "Citoplasma" to "Medio interno donde ocurren procesos celulares"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Límite que regula intercambios.", listOf("Membrana celular", "Citoplasma"), 0, "Membrana celular: Límite que regula intercambios."), ShortQuestion("Una estructura celular regula qué sustancias entran y salen. ¿Cuál es?", listOf("Membrana celular", "Citoplasma"), 0, "Membrana celular: Límite que regula intercambios.")), null, "es-MX", null, gapAnswer = "Membrana celular"),
        ShortLesson("BIOLOGIA:0:1", MateriaId.BIOLOGIA, 0, "Tipos celulares", "Las células eucariotas poseen un núcleo delimitado por membrana. Las procariotas carecen de ese núcleo.", "Las células animales y vegetales son eucariotas. Las bacterias son procariotas.", "Eucariota: Célula con núcleo delimitado.", listOf("Eucariota" to "Célula con núcleo delimitado", "Procariota" to "Célula sin núcleo delimitado"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Célula con núcleo delimitado.", listOf("Eucariota", "Procariota"), 0, "Eucariota: Célula con núcleo delimitado."), ShortQuestion("Observas una bacteria que no tiene núcleo delimitado por membrana. ¿Qué tipo celular es?", listOf("Eucariota", "Procariota"), 1, "Procariota: Célula sin núcleo delimitado.")), null, "es-MX", null, gapAnswer = "Eucariota"),
        ShortLesson("BIOLOGIA:1:0", MateriaId.BIOLOGIA, 1, "ADN y genes", "El ADN almacena información hereditaria. Un gen es una región de ADN que contribuye a producir un producto funcional.", "Una variante de un gen puede cambiar la secuencia de una proteína y modificar su funcionamiento.", "ADN: Molécula que almacena información hereditaria.", listOf("ADN" to "Molécula que almacena información hereditaria", "Gen" to "Región de ADN con función biológica"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Molécula que almacena información hereditaria.", listOf("ADN", "Gen"), 0, "ADN: Molécula que almacena información hereditaria."), ShortQuestion("Identificas una región de ADN que contribuye a producir una proteína. ¿Qué has identificado?", listOf("ADN", "Gen"), 1, "Gen: Región de ADN con función biológica.")), null, "es-MX", null, gapAnswer = "ADN"),
        ShortLesson("BIOLOGIA:1:1", MateriaId.BIOLOGIA, 1, "Ecosistemas", "Un ecosistema incluye organismos y su ambiente físico. Los productores generan materia orgánica y los consumidores la obtienen de otros organismos.", "En una pradera, el pasto es productor y el conejo que lo come es consumidor.", "Productor: Organismo que genera materia orgánica a partir de fuentes inorgánicas.", listOf("Productor" to "Organismo que genera materia orgánica a partir de fuentes inorgánicas", "Consumidor" to "Organismo que se alimenta de otros organismos"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Organismo que genera materia orgánica a partir de fuentes inorgánicas.", listOf("Productor", "Consumidor"), 0, "Productor: Organismo que genera materia orgánica a partir de fuentes inorgánicas."), ShortQuestion("Un conejo obtiene alimento al comer plantas. ¿Qué papel cumple?", listOf("Productor", "Consumidor"), 1, "Consumidor: Organismo que se alimenta de otros organismos.")), null, "es-MX", null, gapAnswer = "Productor"),
        ShortLesson("HISTORIA:0:0", MateriaId.HISTORIA, 0, "Fuentes históricas", "Las fuentes permiten investigar el pasado. Una fuente primaria procede del periodo o proceso estudiado; una secundaria lo analiza posteriormente.", "Una carta escrita durante una guerra es fuente primaria. Un estudio posterior sobre esa guerra es secundario.", "Fuente primaria: Testimonio del periodo estudiado.", listOf("Fuente primaria" to "Testimonio del periodo estudiado", "Fuente secundaria" to "Análisis posterior de fuentes"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Testimonio del periodo estudiado.", listOf("Fuente primaria", "Fuente secundaria"), 0, "Fuente primaria: Testimonio del periodo estudiado."), ShortQuestion("Investigas 1910 y consultas una carta escrita ese año. ¿Cómo se clasifica esa fuente?", listOf("Fuente primaria", "Fuente secundaria"), 0, "Fuente primaria: Testimonio del periodo estudiado.")), null, "es-MX", null, gapAnswer = "Fuente primaria"),
        ShortLesson("HISTORIA:0:1", MateriaId.HISTORIA, 0, "Cronología", "La cronología sitúa acontecimientos en el tiempo. Una secuencia temporal no demuestra por sí sola una relación causal.", "Que una reforma ocurra antes de una protesta no basta para afirmar que la causó: hay que consultar evidencias.", "Cronología: Ordenación temporal de acontecimientos.", listOf("Cronología" to "Ordenación temporal de acontecimientos", "Causalidad" to "Relación por la que un proceso contribuye a otro"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Ordenación temporal de acontecimientos.", listOf("Cronología", "Causalidad"), 0, "Cronología: Ordenación temporal de acontecimientos."), ShortQuestion("Ordenas tres acontecimientos según su fecha, sin afirmar que uno causó otro. ¿Qué estás construyendo?", listOf("Cronología", "Causalidad"), 0, "Cronología: Ordenación temporal de acontecimientos.")), null, "es-MX", null, gapAnswer = "Cronología"),
        ShortLesson("HISTORIA:1:0", MateriaId.HISTORIA, 1, "Causas y consecuencias", "Los procesos históricos suelen tener varias causas. Conviene distinguir las condiciones previas de sus consecuencias y considerar diferentes escalas.", "Para estudiar una migración se examinan empleo, conflictos y redes familiares, además de los cambios en los lugares de origen y destino.", "Causa: Condición que contribuye a un proceso.", listOf("Causa" to "Condición que contribuye a un proceso", "Consecuencia" to "Efecto de un proceso"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Condición que contribuye a un proceso.", listOf("Causa", "Consecuencia"), 0, "Causa: Condición que contribuye a un proceso."), ShortQuestion("Estudias cómo cambió una ciudad después de recibir migrantes. ¿Qué aspecto del proceso analizas?", listOf("Causa", "Consecuencia"), 1, "Consecuencia: Efecto de un proceso.")), null, "es-MX", null, gapAnswer = "Causa"),
        ShortLesson("HISTORIA:1:1", MateriaId.HISTORIA, 1, "Perspectivas", "Una fuente refleja una posición y un contexto. Comparar testimonios permite identificar coincidencias, desacuerdos y silencios.", "Un diario personal y un informe oficial pueden describir de forma distinta el mismo acontecimiento.", "Contexto: Circunstancias en que se produce una fuente.", listOf("Contexto" to "Circunstancias en que se produce una fuente", "Contraste" to "Comparación crítica entre fuentes"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Circunstancias en que se produce una fuente.", listOf("Contexto", "Contraste"), 0, "Contexto: Circunstancias en que se produce una fuente."), ShortQuestion("Comparas un diario y un informe oficial para detectar desacuerdos. ¿Qué operación realizas?", listOf("Contexto", "Contraste"), 1, "Contraste: Comparación crítica entre fuentes.")), null, "es-MX", null, gapAnswer = "Contexto"),
        ShortLesson("GEOLOGIA:0:0", MateriaId.GEOLOGIA, 0, "Minerales y rocas", "Un mineral es un sólido natural con estructura interna ordenada y composición característica. Una roca es un agregado de minerales o material geológico.", "El cuarzo es un mineral. El granito es una roca que contiene varios minerales.", "Mineral: Sólido natural de estructura ordenada.", listOf("Mineral" to "Sólido natural de estructura ordenada", "Roca" to "Agregado de material geológico"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Sólido natural de estructura ordenada.", listOf("Mineral", "Roca"), 0, "Mineral: Sólido natural de estructura ordenada."), ShortQuestion("Una muestra de granito contiene cuarzo, feldespato y mica. ¿Qué es la muestra completa?", listOf("Mineral", "Roca"), 1, "Roca: Agregado de material geológico.")), null, "es-MX", null, gapAnswer = "Mineral"),
        ShortLesson("GEOLOGIA:0:1", MateriaId.GEOLOGIA, 0, "Tipos de rocas", "Las rocas ígneas se forman al solidificarse material fundido. Las sedimentarias se forman por acumulación y consolidación de sedimentos u otros procesos de depósito.", "El basalto es ígneo. Una arenisca se forma a partir de granos de arena consolidados.", "Ígnea: Roca formada al solidificarse material fundido.", listOf("Ígnea" to "Roca formada al solidificarse material fundido", "Sedimentaria" to "Roca formada por procesos de depósito"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Roca formada al solidificarse material fundido.", listOf("Ígnea", "Sedimentaria"), 0, "Ígnea: Roca formada al solidificarse material fundido."), ShortQuestion("La lava se enfría y solidifica. ¿Qué tipo de roca se forma?", listOf("Ígnea", "Sedimentaria"), 0, "Ígnea: Roca formada al solidificarse material fundido.")), null, "es-MX", null, gapAnswer = "Ígnea"),
        ShortLesson("GEOLOGIA:1:0", MateriaId.GEOLOGIA, 1, "Placas tectónicas", "La litosfera está dividida en placas que se desplazan. En límites divergentes se separan; en convergentes se acercan.", "En una dorsal oceánica las placas se separan y se forma nueva corteza oceánica.", "Divergente: Límite donde las placas se separan.", listOf("Divergente" to "Límite donde las placas se separan", "Convergente" to "Límite donde las placas se acercan"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Límite donde las placas se separan.", listOf("Divergente", "Convergente"), 0, "Divergente: Límite donde las placas se separan."), ShortQuestion("En una dorsal oceánica dos placas se separan. ¿Qué límite es?", listOf("Divergente", "Convergente"), 0, "Divergente: Límite donde las placas se separan.")), null, "es-MX", null, gapAnswer = "Divergente"),
        ShortLesson("GEOLOGIA:1:1", MateriaId.GEOLOGIA, 1, "Erosión y depósito", "La erosión retira y transporta material. La sedimentación ocurre cuando ese material se deposita.", "Un río transporta arena y puede depositarla cuando disminuye su capacidad de transporte.", "Erosión: Retirada y transporte de material.", listOf("Erosión" to "Retirada y transporte de material", "Sedimentación" to "Depósito de material transportado"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Retirada y transporte de material.", listOf("Erosión", "Sedimentación"), 0, "Erosión: Retirada y transporte de material."), ShortQuestion("Un río deja arena en una zona de corriente lenta. ¿Qué proceso está ocurriendo?", listOf("Erosión", "Sedimentación"), 1, "Sedimentación: Depósito de material transportado.")), null, "es-MX", null, gapAnswer = "Erosión"),
        ShortLesson("PSICOLOGIA:0:0", MateriaId.PSICOLOGIA, 0, "Conducta y cognición", "La psicología estudia la conducta y los procesos mentales mediante métodos sistemáticos. Distingue lo observable de las inferencias sobre procesos internos.", "Registrar cuánto tarda alguien en responder es una observación; proponer cómo atendió al estímulo es una inferencia.", "Conducta: Actividad observable de un organismo.", listOf("Conducta" to "Actividad observable de un organismo", "Cognición" to "Procesos de adquisición y uso de información"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Actividad observable de un organismo.", listOf("Conducta", "Cognición"), 0, "Conducta: Actividad observable de un organismo."), ShortQuestion("Registras cuántas veces una persona levanta la mano. ¿Qué observas directamente?", listOf("Conducta", "Cognición"), 0, "Conducta: Actividad observable de un organismo.")), null, "es-MX", null, gapAnswer = "Conducta"),
        ShortLesson("PSICOLOGIA:0:1", MateriaId.PSICOLOGIA, 0, "Atención y memoria", "La atención prioriza información para procesarla. La memoria permite conservar y recuperar información; no funciona como una copia exacta de los hechos.", "Atender a una explicación ayuda a codificarla. Intentar recordarla después practica su recuperación.", "Atención: Selección de información para procesarla.", listOf("Atención" to "Selección de información para procesarla", "Memoria" to "Conservación y recuperación de información"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Selección de información para procesarla.", listOf("Atención", "Memoria"), 0, "Atención: Selección de información para procesarla."), ShortQuestion("Sin mirar tus apuntes, intentas recordar un concepto. ¿Qué proceso ejercitas?", listOf("Atención", "Memoria"), 1, "Memoria: Conservación y recuperación de información.")), null, "es-MX", null, gapAnswer = "Atención"),
        ShortLesson("PSICOLOGIA:1:0", MateriaId.PSICOLOGIA, 1, "Aprendizaje", "El aprendizaje produce cambios relativamente duraderos a partir de la experiencia. Un refuerzo aumenta la probabilidad futura de una conducta en un contexto.", "Si una consecuencia hace que una conducta se repita más, cumple una función de refuerzo, aunque no siempre sea un premio material.", "Aprendizaje: Cambio relativamente duradero por experiencia.", listOf("Aprendizaje" to "Cambio relativamente duradero por experiencia", "Refuerzo" to "Consecuencia que aumenta una conducta"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Cambio relativamente duradero por experiencia.", listOf("Aprendizaje", "Refuerzo"), 0, "Aprendizaje: Cambio relativamente duradero por experiencia."), ShortQuestion("Después de una consecuencia, una conducta ocurre más a menudo. ¿Qué función tuvo esa consecuencia?", listOf("Aprendizaje", "Refuerzo"), 1, "Refuerzo: Consecuencia que aumenta una conducta.")), null, "es-MX", null, gapAnswer = "Aprendizaje"),
        ShortLesson("PSICOLOGIA:1:1", MateriaId.PSICOLOGIA, 1, "Investigación", "Una correlación describe una relación estadística. Un experimento manipula una variable y controla otras para investigar efectos.", "Que horas de sueño y resultados de una tarea estén relacionadas no basta para establecer la causa.", "Correlación: Relación estadística entre variables.", listOf("Correlación" to "Relación estadística entre variables", "Experimento" to "Estudio con manipulación y control de variables"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Relación estadística entre variables.", listOf("Correlación", "Experimento"), 0, "Correlación: Relación estadística entre variables."), ShortQuestion("Un estudio encuentra que dos variables cambian juntas, sin manipular ninguna. ¿Qué describe?", listOf("Correlación", "Experimento"), 0, "Correlación: Relación estadística entre variables.")), null, "es-MX", null, gapAnswer = "Correlación"),
        ShortLesson("SOCIOLOGIA:0:0", MateriaId.SOCIOLOGIA, 0, "Sociedad y cultura", "La sociología estudia relaciones, grupos e instituciones. La cultura incluye prácticas, significados, valores y normas compartidos.", "Los saludos varían entre grupos y se aprenden en la interacción social.", "Cultura: Prácticas y significados compartidos.", listOf("Cultura" to "Prácticas y significados compartidos", "Sociedad" to "Conjunto organizado de relaciones sociales"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Prácticas y significados compartidos.", listOf("Cultura", "Sociedad"), 0, "Cultura: Prácticas y significados compartidos."), ShortQuestion("Un grupo comparte formas de saludo y significados asociados a ellas. ¿De qué forman parte?", listOf("Cultura", "Sociedad"), 0, "Cultura: Prácticas y significados compartidos.")), null, "es-MX", null, gapAnswer = "Cultura"),
        ShortLesson("SOCIOLOGIA:0:1", MateriaId.SOCIOLOGIA, 0, "Normas y roles", "Las normas son expectativas de conducta. Los roles agrupan expectativas asociadas a una posición social.", "En una clase se espera que el docente oriente la actividad y que el alumnado participe: son expectativas de rol.", "Norma: Expectativa de conducta compartida.", listOf("Norma" to "Expectativa de conducta compartida", "Rol" to "Expectativas vinculadas a una posición"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Expectativa de conducta compartida.", listOf("Norma", "Rol"), 0, "Norma: Expectativa de conducta compartida."), ShortQuestion("Una posición de docente conlleva expectativas sobre orientar una clase. ¿Qué concepto corresponde?", listOf("Norma", "Rol"), 1, "Rol: Expectativas vinculadas a una posición.")), null, "es-MX", null, gapAnswer = "Norma"),
        ShortLesson("SOCIOLOGIA:1:0", MateriaId.SOCIOLOGIA, 1, "Instituciones", "Las instituciones son patrones relativamente estables que organizan la vida social. La socialización permite aprender formas de participar en ella.", "La familia y la escuela intervienen en la socialización y pueden transmitir normas diferentes.", "Institución: Patrón estable que organiza relaciones sociales.", listOf("Institución" to "Patrón estable que organiza relaciones sociales", "Socialización" to "Aprendizaje de prácticas y normas sociales"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Patrón estable que organiza relaciones sociales.", listOf("Institución", "Socialización"), 0, "Institución: Patrón estable que organiza relaciones sociales."), ShortQuestion("Una persona aprende las normas de un grupo mediante la convivencia. ¿Qué proceso ocurre?", listOf("Institución", "Socialización"), 1, "Socialización: Aprendizaje de prácticas y normas sociales.")), null, "es-MX", null, gapAnswer = "Institución"),
        ShortLesson("SOCIOLOGIA:1:1", MateriaId.SOCIOLOGIA, 1, "Desigualdad", "La desigualdad social implica una distribución diferente de recursos y oportunidades. Analizarla requiere observar estructuras además de decisiones individuales.", "Dos personas pueden estudiar con esfuerzos similares y disponer de distinto acceso a transporte o conexión a internet.", "Recurso: Medio disponible para actuar.", listOf("Recurso" to "Medio disponible para actuar", "Oportunidad" to "Posibilidad efectiva de acceder a una actividad"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Medio disponible para actuar.", listOf("Recurso", "Oportunidad"), 0, "Recurso: Medio disponible para actuar."), ShortQuestion("Una computadora disponible para estudiar es un medio concreto. ¿Cómo se clasifica?", listOf("Recurso", "Oportunidad"), 0, "Recurso: Medio disponible para actuar.")), null, "es-MX", null, gapAnswer = "Recurso"),
        ShortLesson("TECNOLOGIA:0:0", MateriaId.TECNOLOGIA, 0, "Hardware y software", "El hardware son los componentes físicos de un sistema informático. El software son programas e instrucciones que ese sistema ejecuta.", "El teclado es hardware. El programa que procesa lo que escribes es software.", "Hardware: Componentes físicos de un sistema.", listOf("Hardware" to "Componentes físicos de un sistema", "Software" to "Programas e instrucciones"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Componentes físicos de un sistema.", listOf("Hardware", "Software"), 0, "Hardware: Componentes físicos de un sistema."), ShortQuestion("Instalas un programa para editar texto. ¿Qué tipo de componente agregas?", listOf("Hardware", "Software"), 1, "Software: Programas e instrucciones.")), null, "es-MX", null, gapAnswer = "Hardware"),
        ShortLesson("TECNOLOGIA:0:1", MateriaId.TECNOLOGIA, 0, "Algoritmos", "Un algoritmo es una secuencia definida de pasos para resolver una tarea. Debe especificar entradas, operaciones y resultados.", "Para calcular un promedio: sumar las notas y dividir entre la cantidad de notas.", "Entrada: Datos que recibe un algoritmo.", listOf("Entrada" to "Datos que recibe un algoritmo", "Salida" to "Resultado que produce un algoritmo"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Datos que recibe un algoritmo.", listOf("Entrada", "Salida"), 0, "Entrada: Datos que recibe un algoritmo."), ShortQuestion("Un algoritmo recibe notas y devuelve su promedio. ¿Qué es el promedio devuelto?", listOf("Entrada", "Salida"), 1, "Salida: Resultado que produce un algoritmo.")), null, "es-MX", null, gapAnswer = "Entrada"),
        ShortLesson("TECNOLOGIA:1:0", MateriaId.TECNOLOGIA, 1, "Datos y variables", "Una variable permite identificar un valor que un programa utiliza. El tipo de dato establece qué valores y operaciones admite.", "Una variable edad puede contener un entero; nombre puede contener texto.", "Entero: Tipo para números sin parte fraccionaria.", listOf("Entero" to "Tipo para números sin parte fraccionaria", "Cadena" to "Tipo para secuencias de caracteres"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Tipo para números sin parte fraccionaria.", listOf("Entero", "Cadena"), 0, "Entero: Tipo para números sin parte fraccionaria."), ShortQuestion("Necesitas guardar el nombre Ana. ¿Qué tipo de dato corresponde?", listOf("Entero", "Cadena"), 1, "Cadena: Tipo para secuencias de caracteres.")), null, "es-MX", null, gapAnswer = "Entero"),
        ShortLesson("TECNOLOGIA:1:1", MateriaId.TECNOLOGIA, 1, "Redes", "Una red conecta dispositivos para intercambiar datos. Un cliente solicita un servicio y un servidor atiende solicitudes.", "Al abrir una página, el navegador solicita recursos a un servidor web.", "Cliente: Componente que solicita un servicio.", listOf("Cliente" to "Componente que solicita un servicio", "Servidor" to "Componente que atiende solicitudes"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Componente que solicita un servicio.", listOf("Cliente", "Servidor"), 0, "Cliente: Componente que solicita un servicio."), ShortQuestion("Un navegador solicita una página a otro equipo. ¿Qué papel cumple el navegador?", listOf("Cliente", "Servidor"), 0, "Cliente: Componente que solicita un servicio.")), null, "es-MX", null, gapAnswer = "Cliente"),
        ShortLesson("ESCRITURA:0:0", MateriaId.ESCRITURA, 0, "Propósito y destinatario", "Antes de escribir conviene definir qué se quiere lograr y para quién se escribe. Eso orienta el contenido y el registro.", "Un aviso de cambio de horario necesita fecha y acción concreta; un ensayo desarrolla una postura.", "Propósito: Resultado que busca un texto.", listOf("Propósito" to "Resultado que busca un texto", "Destinatario" to "Persona o grupo al que se dirige"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Resultado que busca un texto.", listOf("Propósito", "Destinatario"), 0, "Propósito: Resultado que busca un texto."), ShortQuestion("Decides que tu texto estará dirigido a estudiantes de primer ingreso. ¿Qué has definido?", listOf("Propósito", "Destinatario"), 1, "Destinatario: Persona o grupo al que se dirige.")), null, "es-MX", null, gapAnswer = "Propósito"),
        ShortLesson("ESCRITURA:0:1", MateriaId.ESCRITURA, 0, "El párrafo", "Un párrafo desarrolla una idea principal con detalles pertinentes. La relación entre sus oraciones debe poder seguirse.", "Para explicar un resultado, presenta primero el hallazgo y después los datos que lo sostienen.", "Idea principal: Contenido central de un párrafo.", listOf("Idea principal" to "Contenido central de un párrafo", "Detalle" to "Información que desarrolla la idea"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Contenido central de un párrafo.", listOf("Idea principal", "Detalle"), 0, "Idea principal: Contenido central de un párrafo."), ShortQuestion("Añades una cifra que explica la afirmación central del párrafo. ¿Qué función cumple esa cifra?", listOf("Idea principal", "Detalle"), 1, "Detalle: Información que desarrolla la idea.")), null, "es-MX", null, gapAnswer = "Idea principal"),
        ShortLesson("ESCRITURA:1:0", MateriaId.ESCRITURA, 1, "Argumentación", "Un argumento relaciona una afirmación con razones y evidencia. Una opinión sin apoyo no constituye por sí sola una demostración.", "«La biblioteca debe ampliar su horario» es una propuesta; los registros de demanda pueden aportar evidencia.", "Tesis: Postura que se defiende.", listOf("Tesis" to "Postura que se defiende", "Evidencia" to "Información que respalda una afirmación"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Postura que se defiende.", listOf("Tesis", "Evidencia"), 0, "Tesis: Postura que se defiende."), ShortQuestion("Usas registros de asistencia para respaldar una propuesta de horario. ¿Qué aportan esos registros?", listOf("Tesis", "Evidencia"), 1, "Evidencia: Información que respalda una afirmación.")), null, "es-MX", null, gapAnswer = "Tesis"),
        ShortLesson("ESCRITURA:1:1", MateriaId.ESCRITURA, 1, "Revisión", "Revisar implica comprobar estructura, claridad y precisión. Corregir ortografía es una parte de ese proceso.", "Si un texto repite una idea, puede fusionar párrafos antes de revisar tildes y signos.", "Revisión: Evaluación del contenido y la organización.", listOf("Revisión" to "Evaluación del contenido y la organización", "Corrección" to "Enmienda de errores formales"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Evaluación del contenido y la organización.", listOf("Revisión", "Corrección"), 0, "Revisión: Evaluación del contenido y la organización."), ShortQuestion("Reordenas dos párrafos para que el argumento sea más claro. ¿Qué proceso estás realizando?", listOf("Revisión", "Corrección"), 0, "Revisión: Evaluación del contenido y la organización.")), null, "es-MX", null, gapAnswer = "Revisión"),
        ShortLesson("ANATOMIA:0:0", MateriaId.ANATOMIA, 0, "Posición anatómica", "La posición anatómica sirve como referencia: cuerpo erguido, mirada al frente, brazos a los lados y palmas hacia delante.", "En esta referencia, anterior indica hacia el frente del cuerpo y posterior hacia la espalda.", "Anterior: Hacia la parte frontal del cuerpo.", listOf("Anterior" to "Hacia la parte frontal del cuerpo", "Posterior" to "Hacia la parte trasera del cuerpo"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Hacia la parte frontal del cuerpo.", listOf("Anterior", "Posterior"), 0, "Anterior: Hacia la parte frontal del cuerpo."), ShortQuestion("En posición anatómica, una estructura está hacia la espalda. ¿Qué término describe esa dirección?", listOf("Anterior", "Posterior"), 1, "Posterior: Hacia la parte trasera del cuerpo.")), null, "es-MX", null, gapAnswer = "Anterior"),
        ShortLesson("ANATOMIA:0:1", MateriaId.ANATOMIA, 0, "Planos anatómicos", "Los planos describen divisiones de referencia del cuerpo. El sagital separa porciones derecha e izquierda; el transversal separa superior e inferior.", "Un corte transversal del tronco permite observar estructuras a una misma altura.", "Sagital: Plano que separa derecha e izquierda.", listOf("Sagital" to "Plano que separa derecha e izquierda", "Transversal" to "Plano que separa superior e inferior"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Plano que separa derecha e izquierda.", listOf("Sagital", "Transversal"), 0, "Sagital: Plano que separa derecha e izquierda."), ShortQuestion("Un corte separa una porción superior y otra inferior del cuerpo. ¿Qué plano utiliza?", listOf("Sagital", "Transversal"), 1, "Transversal: Plano que separa superior e inferior.")), null, "es-MX", null, gapAnswer = "Sagital"),
        ShortLesson("ANATOMIA:1:0", MateriaId.ANATOMIA, 1, "Tejidos", "Un tejido reúne células y material extracelular organizados para funciones relacionadas. El epitelial recubre superficies y el muscular produce fuerza por contracción.", "La epidermis es tejido epitelial. Los músculos esqueléticos contienen tejido muscular especializado.", "Epitelial: Tejido que recubre superficies.", listOf("Epitelial" to "Tejido que recubre superficies", "Muscular" to "Tejido especializado en contracción"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Tejido que recubre superficies.", listOf("Epitelial", "Muscular"), 0, "Epitelial: Tejido que recubre superficies."), ShortQuestion("Identificas el tejido que recubre la superficie de la piel. ¿Qué tipo es?", listOf("Epitelial", "Muscular"), 0, "Epitelial: Tejido que recubre superficies.")), null, "es-MX", null, gapAnswer = "Epitelial"),
        ShortLesson("ANATOMIA:1:1", MateriaId.ANATOMIA, 1, "Órganos y sistemas", "Un órgano integra distintos tejidos. Un sistema reúne estructuras que colaboran en funciones del organismo.", "El corazón es un órgano. Junto con vasos sanguíneos forma parte del sistema cardiovascular.", "Órgano: Estructura compuesta por varios tejidos.", listOf("Órgano" to "Estructura compuesta por varios tejidos", "Sistema" to "Conjunto de estructuras que colaboran"), listOf(ShortQuestion("¿Qué concepto corresponde a esta definición? Estructura compuesta por varios tejidos.", listOf("Órgano", "Sistema"), 0, "Órgano: Estructura compuesta por varios tejidos."), ShortQuestion("El corazón integra varios tejidos en una estructura. ¿Cómo se clasifica?", listOf("Órgano", "Sistema"), 0, "Órgano: Estructura compuesta por varios tejidos.")), null, "es-MX", null, gapAnswer = "Órgano"),
